#[path="../native-smith-transport/pic.rs"]mod pic;
#[path="../native-smith-transport/models.rs"]mod models;
#[path="../native-smith-transport/transport.rs"]mod transport;
mod ic;
use hec_native_ic::{counted,instance::pick_instance,rng::Rng};
fn main(){counted::reset();let inst=pick_instance(61,3).unwrap();assert_eq!(inst.c,5);assert_eq!(inst.ell,124459);let c=&inst.curve;let mut rng=Rng::new(2026111800^61^(3<<32));let fixtures=(0..2).map(|case|{let multiple=if case==0{1}else{17};let d=c.mul(&inst.d1,multiple);let verification_scalar=1+rng.below(inst.ell-1);let t=c.mul(&d,verification_scalar);(case,multiple,d,t,verification_scalar)}).collect::<Vec<_>>();for(map,model)in models::models().iter().enumerate(){let p0=pic::first_rational_point_canonical(61,&model.coeff).unwrap();let pc=pic::PlaneQuartic::new(61,model.coeff,p0).unwrap();let base=ic::build(&pc,inst.ell,map);println!("BASE_COST map={map} lines={} split_lines={} pic={:?} native_partial={:?}",base.lines,base.split_lines,base.relation_pic_cost,counted::snapshot());for(case,multiple,d,t,label)in &fixtures{let source=transport::transport(c,d,&inst.d1,model,&pc,1).unwrap();let target=transport::transport(c,t,&inst.d1,model,&pc,1).unwrap();let report=ic::solve(&pc,&source.class,&target.class,inst.ell,&base,2026112400^(map as u64)^((*case as u64)<<32)).expect("quartic IC budget exhausted");assert_eq!(report.k,*label);assert_eq!(c.mul(d,report.k),*t,"original hyperelliptic final verification");println!("SOLVE map={map} case={case} source_multiple={multiple} k={} original_h_verified=true report={report:?}",report.k);}println!("MAP map={map} final_pic_stats={:?}",pc.stats());}counted::disable();eprintln!("PASS original_quartic_ic_solves=4 all_returned_scalars_verified_on_original_H=true known_labels_only_in_driver=true no_end_to_end_speed_claim=true");}
